(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.016+t*0.28)*11 + Math.cos((x-y)*0.009-t*0.12)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*10 + Math.cos(sy*0.02+t*0.35)*8;
  const w2y = Math.cos(sy*0.023+t*0.38)*9 + Math.sin(sx*0.019-t*0.32)*7;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 0],
    [320+Math.cos(t*0.45)*105, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 1],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.4, 2],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.5],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.5],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 2.5],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+4)*50, 0.1, 1.9, 3],
    [420+Math.cos(t*0.4+2)*60, 200+Math.sin(t*0.65+1)*55, 0.07, 2.5, 0.8]
  ];
  let aS=0, iS=0, aS2=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((px-sX)**2+(py-sY)**2);
    aS += Math.sin(d*f - t*sp + ph);
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + ph + 1.7);
    aS2 += Math.sin(d*f*1.3 - t*sp*1.4 + ph*0.5);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8;
  const n1 = Math.sin(px*0.035+py*0.022+t*0.7);
  const n2 = Math.sin(px*0.028-py*0.038+t*0.95);
  const n3 = Math.sin((px+py)*0.11+t*2.2)*0.25;
  const n4 = Math.sin((px-py)*0.095-t*1.8)*0.25;
  const bg = (n1+n2)/2 + n3 + n4;
  const dist = Math.sqrt((px-cx)**2+(py-cy)**2);
  const ang = Math.atan2(py-cy, px-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const gx = px*0.13, gy = py*0.13;
  const voronoi = Math.sin(gx)*Math.sin(gy)+Math.sin(gx*1.5+0.7)*Math.sin(gy*1.3+1.1)*0.5+Math.sin(gx*0.7+2.1)*Math.sin(gy*0.8+0.5)*0.3;
  const cell = Math.tanh(voronoi*1.4)*0.25;
  const fbm = n1*0.5 + n2*0.3 + n3*0.2;
  const reaction = Math.tanh((act*0.5+act2*0.2 - inh*0.65 + bg*0.25 + spiral*0.3 + fbm*0.15)*2.0);
  const blend = reaction*0.65 + cell*0.2 + Math.tanh(act2*0.8)*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[8,35,82],[12,68,105],[18,108,125],
    [35,148,135],[120,170,90],[195,185,55],
    [225,145,50],[215,95,55],[185,50,60],
    [130,30,65],[65,18,55],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const c0=pal[i], c1=pal[i+1];
  const r=c0[0]+(c1[0]-c0[0])*f, g=c0[1]+(c1[1]-c0[1])*f, b=c0[2]+(c1[2]-c0[2])*f;
  const edge = Math.abs(reaction)>0.65 ? 1.0+Math.abs(reaction)*0.25 : 1.0;
  const glow = Math.max(0, Math.abs(reaction)-0.6)*2.5;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const shimmer = 1.0+Math.sin(dist*0.08-t*3)*0.05*(Math.abs(reaction)>0.5?1:0);
  const m = lum*edge*shimmer;
  return [
    Math.min(255, (r*m + glow*40)|0),
    Math.min(255, (g*m + glow*25)|0),
    Math.min(255, (b*m + glow*15)|0)
  ];
}
